import {start,e,field,select,uid} from '../workshop-kit/ui.js?v=0.20.0';
import {model,LEVELS,STATUS,linkTitle,markdown} from './state.js?v=0.20.0';
import {sourceDetails,familyMap} from '../shared/ancestry-ui.js?v=0.20.0';
const name=s=>s.name.trim()||'Unnamed step';
const review=o=>o.review?'Context changed · review needed':o.checked?'Context reviewed · hypothesis unproven':'Not reviewed';
const optionField=(o,k,label,help='')=>field('option-'+k,label,o[k],{type:'option',id:o.id,field:k},help);
function card(o,w){return `<article class="intervention-chip ${w.selectedId===o.id?'selected':''}" data-drag-id="option:${e(o.id)}"><div><button class="option-title" data-act="inspect" data-id="${e(o.id)}">${e(o.title||'Name this intervention…')}</button><p class="anchor-label">${e(LEVELS[o.level].name)} · ${o.linkId?'relationship attached':'step only'}</p><span class="review-tag" data-review-option="${e(o.id)}">${review(o)}</span></div><button class="drag-handle" data-drag-handle data-act="target-menu" data-id="${e(o.id)}" aria-label="Attach ${e(o.title||'intervention')} to a relationship">⠿</button></article>`;}
function comparison(w){const options=w.compareIds.map(id=>w.options.find(o=>o.id===id));if(!options.length)return '<p>Add up to four interventions from the notebook to compare their predictions and tests.</p>';const rows=[['Relationship',o=>o.linkId?linkTitle(w,w.links.find(l=>l.id===o.linkId)):'No relationship attached'],['Change',o=>o.change],['Why it should work',o=>o.why],['Expected observation',o=>o.expected],['Competing explanation',o=>o.competing],['How to distinguish it',o=>o.observe],['Smallest test',o=>o.test],['What would change my mind',o=>o.evidence],['Cost or permission',o=>o.tradeoff],['Review',o=>review(o)]];return `<p class="microcopy">Compare claims, not scores. Scroll sideways through alternatives ↔.</p><div class="comparison-scroll" tabindex="0" role="region" aria-label="Intervention comparison; scroll sideways"><table><thead><tr><th scope="col">Question</th>${options.map(o=>`<th scope="col"><button class="text-button" data-act="inspect" data-id="${e(o.id)}">${e(o.title||'Untitled intervention')}</button><button class="text-button" data-act="compare" data-id="${e(o.id)}" aria-label="Remove ${e(o.title||'intervention')} from comparison">Remove</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,get])=>`<tr><th scope="row">${label}</th>${options.map(o=>`<td>${e(get(o)||'Not written')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function notebook(o,w){return `<section class="option-notebook" id="option-notebook"><div class="section-top"><div><span class="eyebrow">DEVELOP AN INTERVENTION</span><h2 id="notebook-title">${e(o.title||'A possible change')}</h2></div><div class="notebook-actions"><button class="button" data-act="branch" data-id="${e(o.id)}" ${w.options.length>=24?'disabled':''}>Branch a variation</button><button class="text-button danger" data-act="remove" data-id="${e(o.id)}">Remove</button></div></div><p class="review-tag" data-review-option="${e(o.id)}">${review(o)}</p>${select('option-target','Which causal relationship would change?',o.linkId||'',[['','Not attached · retain step context'],...w.links.map(l=>[l.id,linkTitle(w,l)])],{type:'target',id:o.id})}<p class="attached-context">${o.linkId?e(linkTitle(w,w.links.find(l=>l.id===o.linkId))):'Step context: '+e(name(w.steps.find(s=>s.id===o.anchor)))}</p><div class="option-fields">${optionField(o,'title','Name the intervention')}${optionField(o,'change','What changes?',LEVELS[o.level].prompt)}${optionField(o,'why','Why should that change the outcome?','Identify what changes in the relationship, not only the activity.')}${optionField(o,'expected','What would you expect to observe?','Describe the difference, where it appears, and when.')}</div><details class="working-details"><summary>Challenge the explanation and design a test</summary><div class="option-fields">${optionField(o,'competing','What else could produce that observation?','For example: a quieter week, a different mix of requests, or extra attention.')}${optionField(o,'observe','How would you distinguish the explanations?','Name a comparison or another observation that separates them.')}${optionField(o,'test','The smallest useful test','Who does what, for how long, with which limit on effort?')}${optionField(o,'evidence','What would change your mind?','Which observation would make you stop, revise, or continue?')}${optionField(o,'tradeoff','What does it cost or require?','Include permissions, side effects, and work shifted elsewhere.')}</div></details>${o.ancestry.parents.length?`<div class="option-fields">${optionField(o,'changed','What changes in this variation?')}${optionField(o,'reason','Why try this variation?')}</div>${sourceDetails(o.ancestry)}`:''}<div class="choose-row"><button class="button" data-act="reviewed" data-id="${e(o.id)}">Record a context review</button><button class="button" data-act="compare" data-id="${e(o.id)}" aria-pressed="${w.compareIds.includes(o.id)}">${w.compareIds.includes(o.id)?'In comparison · remove':'Add to comparison'}</button><button class="button primary" data-act="choose" data-id="${e(o.id)}">${w.chosenId===o.id?'Chosen for a test':'Choose for a test'}</button></div><p class="microcopy">A review records the wording you checked. Choosing a test does not validate the hypothesis.</p>${o.checked?`<details class="working-details"><summary>Last reviewed context</summary>${sourceDetails({version:1,parents:[o.checked],parked:false})}</details>`:''}</section>`;}
function render(w){const selected=w.options.find(o=>o.id===w.selectedId);return `<div class="section-top"><div><h2>Which relationship would you change?</h2><p>Connect a possible cause to its effect. Then compare interventions by what you would expect to observe.</p></div><button class="button" data-act="add-step" ${w.steps.length>=7?'disabled':''}>+ Step</button></div><p class="microcopy">Drag a step’s connector onto another step, or use its Connect button. Step order is layout; it does not establish cause. Scroll through the steps ↔.</p><section class="steps-scroll" tabindex="0" role="region" aria-label="Mechanism steps; scroll sideways"><div class="mechanism-canvas">${w.steps.map((s,i)=>`<article class="mechanism-step" data-drag-id="step:${e(s.id)}" data-drop-id="step:${e(s.id)}"><span class="eyebrow">STEP ${i+1}</span><button class="step-title" data-act="edit-step" data-id="${e(s.id)}"><strong>${e(name(s))}</strong><span>${e(s.mechanism||'Describe the event or condition.')}</span></button><div class="step-actions"><button class="text-button drag-handle" data-drag-handle data-act="connect" data-id="${e(s.id)}" aria-label="Connect from ${e(name(s))}">Connect →</button><button class="text-button" data-act="reorder" data-id="${e(s.id)}" data-dir="-1" aria-label="Move step ${i+1} earlier" ${i===0?'disabled':''}>←</button><button class="text-button" data-act="reorder" data-id="${e(s.id)}" data-dir="1" aria-label="Move step ${i+1} later" ${i===w.steps.length-1?'disabled':''}>→</button></div></article>`).join('')}</div></section><div class="section-top relationship-heading"><div><span class="eyebrow">PROPOSED CAUSAL RELATIONSHIPS</span><p>What makes one event affect another, under which conditions?</p></div><button class="button" data-act="connect" ${w.links.length>=18||w.steps.length<2?'disabled':''}>+ Relationship</button></div><section class="relationships">${w.links.map(l=>`<article class="relationship" data-drop-id="link:${e(l.id)}"><button class="relationship-title" data-act="edit-link" data-id="${e(l.id)}">${e(linkTitle(w,l))}</button><span class="review-tag" data-review-link="${e(l.id)}">${e(STATUS[l.status])}${l.review?' · review needed':''}</span><p>${e(l.mechanism||'Causal claim not written.')}</p>${l.origin==='sequence'?'<p class="microcopy">Suggested from earlier step order; the claim still needs checking.</p>':''}<div class="relationship-options">${w.options.filter(o=>o.linkId===l.id).map(o=>card(o,w)).join('')||'<p class="drop-hint">Drop an intervention here to target this relationship.</p>'}</div><button class="text-button" data-act="add-option" data-key="${e(l.id)}" ${w.options.length>=24?'disabled':''}>+ Intervention here</button></article>`).join('')||'<p>No causal links yet. Connect two steps to write the first hypothesis.</p>'}</section><section class="unattached"><div class="section-top"><h2>Ideas without a relationship</h2><button class="text-button" data-act="add-option" ${w.options.length>=24?'disabled':''}>+ Intervention</button></div><div class="unattached-list">${w.options.filter(o=>!o.linkId).map(o=>card(o,w)).join('')||'<p>All current interventions are attached.</p>'}</div></section>${selected?notebook(selected,w):'<p class="empty-note">Add an intervention to develop its claim and test.</p>'}<section class="comparison-panel"><h2>Compare the tests you could run</h2><div id="comparison-content">${comparison(w)}</div><p id="chosen-test">${w.chosenId?'Chosen for a test: '+e(w.options.find(o=>o.id===w.chosenId).title||'Untitled intervention'):'No test chosen yet.'}</p>${field('decision','Decision and remaining uncertainty',w.decision,{type:'decision'},'Why this test, what must be true, and what do you still need to learn?')}</section><details class="working-details prompt-library"><summary>Try another kind of change</summary><p>These are prompts, not a ranking. Changing an intervention’s type does not demonstrate an effect.</p><div class="prompt-grid">${Object.entries(LEVELS).map(([key,l])=>`<section class="prompt" data-drop-id="level:${key}"><h3>${l.name}</h3><p>${l.prompt}</p>${selected?`<button class="text-button" data-act="level" data-id="${e(selected.id)}" data-kind="${key}">${selected.level===key?'Current type':'Use for selected intervention'}</button>`:''}<span class="microcopy">Drop an intervention to change its type.</span></section>`).join('')}</div></details>${w.options.some(o=>o.ancestry.parents.length)?`<details class="working-details"><summary>Follow intervention variations</summary>${familyMap(w.options.map(o=>({...o,mechanism:o.why})),{action:'inspect',attribute:'data-act'})}</details>`:''}`;}
function editStep(id,m){const s=m.work().steps.find(s=>s.id===id);m.open(`${field('step-name','Step, event or condition',s.name,{type:'step',id,field:'name'})}${field('step-mechanism','What happens here?',s.mechanism,{type:'step',id,field:'mechanism'})}<p class="microcopy">Editing this step flags its relationships and interventions for review.</p><button class="text-button danger" data-act="remove-step" data-id="${e(id)}">Remove step</button>`,'Describe this step');}
function editLink(id,m){const w=m.work(),l=w.links.find(l=>l.id===id);m.open(`<p class="dialog-description">${e(linkTitle(w,l))}</p>${[['mechanism','How does the cause affect the outcome?'],['conditions','When does this relationship hold?'],['lag','When would the effect appear?'],['alternative','What rival explanation could account for it?'],['observations','What have you actually observed?']].map(([k,label])=>field('link-'+k,label,l[k],{type:'link',id,field:k})).join('')}${select('link-status','What do those observations suggest?',l.status,Object.entries(STATUS),{type:'link-status',id})}<p class="microcopy">Consistent observations do not establish causation. A changed claim retains its observations and requests review.</p><div class="choose-row"><button class="button" data-act="review-link" data-id="${e(id)}">Record a context review</button><button class="text-button danger" data-act="remove-link" data-id="${e(id)}">Remove relationship</button></div>${l.checked?sourceDetails({version:1,parents:[l.checked],parked:false}):''}`,'Examine the causal claim');}
function connect(from,m){const w=m.work(),options=w.steps.map(s=>[s.id,name(s)]);if(w.steps.length<2){m.toast('Add a second step to connect a relationship.');return;}m.open(`<p class="dialog-description">Direction matters. A feedback relationship can point back to an earlier step.</p><div class="field"><label for="connect-from">Possible cause</label><select id="connect-from">${options.map(([id,label])=>`<option value="${e(id)}" ${id===(from||options[0][0])?'selected':''}>${e(label)}</option>`).join('')}</select></div><div class="field"><label for="connect-to">Possible effect</label><select id="connect-to">${options.map(([id,label])=>`<option value="${e(id)}" ${id===(options.find(([id])=>id!==(from||options[0][0]))?.[0])?'selected':''}>${e(label)}</option>`).join('')}</select></div><button class="button primary" data-act="create-link">Connect these steps</button>`,'Connect a causal hypothesis');}
function attach(id,m){const w=m.work(),o=w.options.find(o=>o.id===id);m.open(`${select('attach-link','Relationship to change',o.linkId||'',[['','No relationship · keep step context'],...w.links.map(l=>[l.id,linkTitle(w,l)])],{type:'target',id})}<details class="working-details"><summary>Attach to a step instead</summary><div class="stack-options">${w.steps.map(s=>`<button data-act="anchor" data-id="${e(id)}" data-key="${e(s.id)}">${e(name(s))}</button>`).join('')}</div></details><p class="microcopy">Your reasoning stays intact; a changed attachment requests review.</p>`,'Attach an intervention');}
function addLink(from,to,m){const existing=m.work().links.find(l=>l.from===from&&l.to===to);if(existing){m.toast('That relationship already exists. Open it to develop its claim.');return existing.id;}const id=uid();return m.update({type:'add-link',id,from,to})?id:null;}
start({route:'interventions',number:'05',kicker:'CHANGE THE MECHANISM',title:'Intervention workbench',engine:model,examples:[['blank','+ My own problem'],['example','Product reviews'],['battery','Battery decisions']],workspaceSummary:w=>`${w.links.length} causal hypotheses · ${w.options.length} interventions`,markdown,render,
 liveEdit:(a,m)=>{const w=m.work();m.root.querySelectorAll('[data-review-option]').forEach(el=>el.textContent=review(w.options.find(o=>o.id===el.dataset.reviewOption)));m.root.querySelectorAll('[data-review-link]').forEach(el=>{const l=w.links.find(l=>l.id===el.dataset.reviewLink);el.textContent=STATUS[l.status]+(l.review?' · review needed':'');});const title=m.root.querySelector('#notebook-title');if(title)title.textContent=w.options.find(o=>o.id===w.selectedId)?.title||'A possible change';m.root.querySelector('#comparison-content').innerHTML=comparison(w);m.root.querySelector('#chosen-test').textContent=w.chosenId?'Chosen for a test: '+(w.options.find(o=>o.id===w.chosenId).title||'Untitled intervention'):'No test chosen yet.';},
 drag:({itemId,dropId},m)=>{const kind=itemId.slice(0,itemId.indexOf(':')),id=itemId.slice(itemId.indexOf(':')+1),target=dropId.slice(0,dropId.indexOf(':')),key=dropId.slice(dropId.indexOf(':')+1);if(kind==='step'&&target==='step'){if(addLink(id,key,m))m.toast('Relationship added. Open it to write the causal claim.');}else if(kind==='option'&&target==='link'){if(m.update({type:'target',id,value:key}))m.toast('Relationship changed. Review the intervention’s reasoning.');}else if(kind==='option'&&target==='level'){const o=m.work().options.find(o=>o.id===id);m.update({type:'move-option',id,level:key,anchor:o.anchor});}else m.toast('Connect a step to a step, or attach an intervention to a relationship.');},
 action:(d,m)=>{const w=m.work(),o=w.options.find(o=>o.id===d.id);
  if(d.act==='inspect'){m.update({type:'select',id:d.id},{checkpoint:false});m.scroll('option-notebook');}
  else if(d.act==='add-step'){const id=uid();if(m.update({type:'add-step',id}))editStep(id,m);}
  else if(d.act==='edit-step')editStep(d.id,m);
  else if(d.act==='reorder')m.update({type:'reorder-step',id:d.id,direction:Number(d.dir)});
  else if(d.act==='remove-step'||d.act==='remove-link'){if(m.update({type:d.act,id:d.id}))m.close();}
  else if(d.act==='connect')connect(d.id,m);
  else if(d.act==='create-link'){const id=addLink(m.dialog.querySelector('#connect-from').value,m.dialog.querySelector('#connect-to').value,m);if(id){m.close();requestAnimationFrame(()=>editLink(id,m));}}
  else if(d.act==='edit-link')editLink(d.id,m);
  else if(d.act==='review-link'){if(m.update({type:'review-link',id:d.id})){m.close();m.toast('Context review recorded. The causal claim remains a hypothesis.');}}
  else if(d.act==='target-menu')attach(d.id,m);
  else if(d.act==='anchor'){if(m.update({type:'step-anchor',id:d.id,value:d.key}))m.close();}
  else if(d.act==='add-option'){const l=w.links.find(l=>l.id===d.key),id=uid();if(m.update({type:'add-option',id,anchor:l?.from||w.steps[0].id,level:'step',linkId:l?.id??null}))m.scroll('option-notebook');}
  else if(d.act==='level')m.update({type:'move-option',id:d.id,anchor:o.anchor,level:d.kind});
  else if(d.act==='branch'){if(m.update({type:'branch',id:d.id,newId:uid()}))m.scroll('option-notebook');}
  else if(['compare','choose','reviewed'].includes(d.act)){if(m.update({type:d.act,id:d.id})&&d.act==='reviewed')m.toast('Context review recorded; this is not evidence that the intervention works.');}
  else if(d.act==='remove')m.update({type:'remove-option',id:d.id});
 }
});
